def render_ilju_card(ilgan_cg: str, ilji_jj: str, name: str = "내담자") -> str:
    """60갑자 일주 정통 풀이 HTML 박스 (자주 테마)"""
    key = ilgan_cg + ilji_jj
    detail = ILJU_60GAPJA.get(key, {})
    if not detail:
        return ""

    h        = detail.get("한글", key)
    sun      = detail.get("순번", "")
    nabeum   = detail.get("납음오행", "")
    nabeum_d = detail.get("납음설명", "")
    wunsung  = detail.get("12운성", "")
    gongmang = detail.get("공망", "")
    byeolch  = detail.get("별칭", "")
    bonsung  = detail.get("본성", "")
    sungyeok = detail.get("성격", "")
    gangjeom = detail.get("강점", "")
    yakjeom  = detail.get("약점", "")
    baewuja  = detail.get("배우자", "")
    jikup    = detail.get("직업", "")
    jaemal   = detail.get("재물", "")
    inyeon   = detail.get("인연", "")
    geongang = detail.get("건강", "")
    ilsaeng  = detail.get("인생흐름", "")
    famous   = detail.get("유명인", "")
    juui     = detail.get("주의", "")
    gaeun    = detail.get("개운", "")

    html = f"""
<div style="background: linear-gradient(135deg, #f5e6f5 0%, #ede0ed 100%);
            border: 2px solid #6a1b9a; border-radius: 16px;
            padding: 24px; margin: 20px 0;
            box-shadow: 0 8px 24px rgba(106, 27, 154, 0.15);">

  <div style="font-size: 20px; font-weight: 900; color: #4a148c;
              text-align: center; margin-bottom: 18px; letter-spacing: 1px;
              border-bottom: 2px solid #6a1b9a; padding-bottom: 12px;">
    🔮 일주 {key}({h}) — 60갑자 {sun}번째 운명 코드
  </div>

  <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:14px;">
    <div style="background:rgba(106,27,154,0.08);border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#4a148c;margin-bottom:4px;">🔥 납음오행(納音五行 — 60갑자별 숨은 오행)</div>
      <div style="font-size:13px;font-weight:700;color:#6a1b9a;">{nabeum}</div>
      <div style="font-size:11px;color:#7b1fa2;line-height:1.5;">{nabeum_d}</div>
    </div>
    <div style="background:rgba(106,27,154,0.08);border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#4a148c;margin-bottom:4px;">⚡ 12운성(十二運星 — 일간의 강약 단계) · 공망(空亡 — 비어있는 자리, 헛수고 주의)</div>
      <div style="font-size:13px;font-weight:700;color:#6a1b9a;">{wunsung}</div>
      <div style="font-size:11px;color:#7b1fa2;">공망: {gongmang}</div>
    </div>
  </div>
  <div style="background:rgba(74,20,140,0.07);border-radius:8px;padding:10px;
              margin-bottom:14px;text-align:center;">
    <span style="font-size:12px;font-weight:700;color:#4a148c;">✨ 별칭: </span>
    <span style="font-size:13px;font-style:italic;color:#6a1b9a;">{byeolch}</span>
  </div>

  <div style="margin-bottom:12px;">
    <div style="font-size:13px;font-weight:800;color:#4a148c;margin-bottom:6px;
                border-left:4px solid #6a1b9a;padding-left:8px;">🌱 본성(本性)</div>
    <div style="font-size:12.5px;color:#37006e;line-height:1.8;padding:10px;
                background:rgba(255,255,255,0.6);border-radius:8px;">{bonsung}</div>
  </div>

  <div style="margin-bottom:12px;">
    <div style="font-size:13px;font-weight:800;color:#4a148c;margin-bottom:6px;
                border-left:4px solid #6a1b9a;padding-left:8px;">💎 성격 특성</div>
    <div style="font-size:12.5px;color:#37006e;line-height:1.8;padding:10px;
                background:rgba(255,255,255,0.6);border-radius:8px;">{sungyeok}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;">
      <div style="background:#e8f5e9;border-radius:8px;padding:8px;">
        <div style="font-size:11px;font-weight:800;color:#1b5e20;margin-bottom:3px;">💪 강점</div>
        <div style="font-size:11px;color:#2e7d32;line-height:1.6;">{gangjeom}</div>
      </div>
      <div style="background:#ffebee;border-radius:8px;padding:8px;">
        <div style="font-size:11px;font-weight:800;color:#b71c1c;margin-bottom:3px;">⚠️ 약점·과제</div>
        <div style="font-size:11px;color:#c62828;line-height:1.6;">{yakjeom}</div>
      </div>
    </div>
  </div>

  <div style="margin-bottom:12px;">
    <div style="font-size:13px;font-weight:800;color:#4a148c;margin-bottom:6px;
                border-left:4px solid #6a1b9a;padding-left:8px;">💑 배우자궁(日支) 분석</div>
    <div style="font-size:12.5px;color:#37006e;line-height:1.8;padding:10px;
                background:rgba(255,255,255,0.6);border-radius:8px;">{baewuja}</div>
  </div>

  <div style="margin-bottom:12px;">
    <div style="font-size:13px;font-weight:800;color:#4a148c;margin-bottom:6px;
                border-left:4px solid #6a1b9a;padding-left:8px;">❤️ 인연 스타일</div>
    <div style="font-size:12.5px;color:#37006e;line-height:1.8;padding:10px;
                background:rgba(255,255,255,0.6);border-radius:8px;">{inyeon}</div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">
    <div style="background:#e3f2fd;border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#0d47a1;margin-bottom:4px;">💼 적합 직업</div>
      <div style="font-size:11px;color:#1565c0;line-height:1.6;">{jikup}</div>
    </div>
    <div style="background:#fff9c4;border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#f57f17;margin-bottom:4px;">💰 재물운</div>
      <div style="font-size:11px;color:#e65100;line-height:1.6;">{jaemal}</div>
    </div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">
    <div style="background:#e8f5e9;border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#1b5e20;margin-bottom:4px;">🏥 건강 주의</div>
      <div style="font-size:11px;color:#2e7d32;line-height:1.6;">{geongang}</div>
    </div>
    <div style="background:#f3e5f5;border-radius:8px;padding:10px;">
      <div style="font-size:11px;font-weight:800;color:#4a148c;margin-bottom:4px;">🌊 인생 흐름</div>
      <div style="font-size:11px;color:#6a1b9a;line-height:1.6;">{ilsaeng}</div>
    </div>
  </div>

  <div style="background:#fce4ec;border-radius:8px;padding:10px;margin-bottom:8px;">
    <div style="font-size:11px;font-weight:800;color:#880e4f;margin-bottom:4px;">⭐ 유명인 (참고)</div>
    <div style="font-size:11px;color:#ad1457;line-height:1.6;">{famous}</div>
  </div>
  <div style="background:#ffebee;border-radius:8px;padding:10px;margin-bottom:8px;">
    <div style="font-size:11px;font-weight:800;color:#b71c1c;margin-bottom:4px;">⚠️ 주의사항</div>
    <div style="font-size:11px;color:#c62828;line-height:1.6;">{juui}</div>
  </div>
  <div style="background:#e8eaf6;border-radius:8px;padding:10px;">
    <div style="font-size:11px;font-weight:800;color:#283593;margin-bottom:4px;">🌟 개운법</div>
    <div style="font-size:11px;color:#303f9f;line-height:1.6;">{gaeun}</div>
  </div>

</div>
"""
    return html


