def render_manse_board(pils, name="내담자", birth_year=1969, gender="男",
                        daewoon_list=None, current_year=2026):
    """정통 사주 상담소 스타일 만세력 보드. 원국 4기둥 + 대운 + 세운 시각 표."""
    if not pils or len(pils) < 4:
        return ""

    from datetime import datetime as _dt

    CG_KR = {"甲":"갑","乙":"을","丙":"병","丁":"정","戊":"무",
              "己":"기","庚":"경","辛":"신","壬":"임","癸":"계"}
    JJ_KR = {"子":"자","丑":"축","寅":"인","卯":"묘","辰":"진","巳":"사",
              "午":"오","未":"미","申":"신","酉":"유","戌":"술","亥":"해"}
    CG_COLOR = {
        "甲":"#2e7d32","乙":"#388e3c",
        "丙":"#c62828","丁":"#d32f2f",
        "戊":"#e65100","己":"#f57f17",
        "庚":"#424242","辛":"#616161",
        "壬":"#1565c0","癸":"#1976d2",
    }
    JJ_COLOR = {
        "寅":"#2e7d32","卯":"#388e3c",
        "巳":"#c62828","午":"#d32f2f",
        "辰":"#e65100","未":"#f57f17","戌":"#fbc02d","丑":"#f9a825",
        "申":"#424242","酉":"#616161",
        "亥":"#1565c0","子":"#1976d2",
    }

    sj = pils[3]; wj = pils[2]; iz = pils[1]; tj = pils[0]
    cg_list = [tj.get("cg",""), iz.get("cg",""), wj.get("cg",""), sj.get("cg","")]
    jj_list = [tj.get("jj",""), iz.get("jj",""), wj.get("jj",""), sj.get("jj","")]
    ilgan = iz.get("cg","")
    nyeon_jj = sj.get("jj","")

    # 인라인 십성 계산 (순환 import 방지)
    def _ss(ig, cg):
        OH = {"甲":"木","乙":"木","丙":"火","丁":"火","戊":"土",
              "己":"土","庚":"金","辛":"金","壬":"水","癸":"水"}
        YY = {"甲":"陽","乙":"陰","丙":"陽","丁":"陰","戊":"陽",
              "己":"陰","庚":"陽","辛":"陰","壬":"陽","癸":"陰"}
        GEN = {"木":"火","火":"土","土":"金","金":"水","水":"木"}
        CTL = {"木":"土","火":"金","土":"水","金":"木","水":"火"}
        if not ig or not cg: return ""
        io, o = OH.get(ig,""), OH.get(cg,"")
        sy = (YY.get(ig,"") == YY.get(cg,""))
        if io == o:         return "비견" if sy else "겁재"
        if GEN.get(o) == io: return "편인" if sy else "정인"
        if GEN.get(io) == o: return "식신" if sy else "상관"
        if CTL.get(o) == io: return "편관" if sy else "정관"
        if CTL.get(io) == o: return "편재" if sy else "정재"
        return ""

    # 지장간
    JJ_JG = {
        "子":"壬·癸","丑":"癸·辛·己","寅":"戊·丙·甲","卯":"甲·乙",
        "辰":"乙·癸·戊","巳":"戊·庚·丙","午":"丙·己·丁","未":"丁·乙·己",
        "申":"戊·壬·庚","酉":"庚·辛","戌":"辛·丁·戊","亥":"戊·甲·壬",
    }

    # 12운성
    UNSEONG = {
        "甲":{"亥":"장생","子":"목욕","丑":"관대","寅":"건록","卯":"제왕","辰":"쇠","巳":"병","午":"사","未":"묘","申":"절","酉":"태","戌":"양"},
        "乙":{"午":"장생","巳":"목욕","辰":"관대","卯":"건록","寅":"제왕","丑":"쇠","子":"병","亥":"사","戌":"묘","酉":"절","申":"태","未":"양"},
        "丙":{"寅":"장생","卯":"목욕","辰":"관대","巳":"건록","午":"제왕","未":"쇠","申":"병","酉":"사","戌":"묘","亥":"절","子":"태","丑":"양"},
        "丁":{"酉":"장생","申":"목욕","未":"관대","午":"건록","巳":"제왕","辰":"쇠","卯":"병","寅":"사","丑":"묘","子":"절","亥":"태","戌":"양"},
        "戊":{"寅":"장생","卯":"목욕","辰":"관대","巳":"건록","午":"제왕","未":"쇠","申":"병","酉":"사","戌":"묘","亥":"절","子":"태","丑":"양"},
        "己":{"酉":"장생","申":"목욕","未":"관대","午":"건록","巳":"제왕","辰":"쇠","卯":"병","寅":"사","丑":"묘","子":"절","亥":"태","戌":"양"},
        "庚":{"巳":"장생","午":"목욕","未":"관대","申":"건록","酉":"제왕","戌":"쇠","亥":"병","子":"사","丑":"묘","寅":"절","卯":"태","辰":"양"},
        "辛":{"子":"장생","亥":"목욕","戌":"관대","酉":"건록","申":"제왕","未":"쇠","午":"병","巳":"사","辰":"묘","卯":"절","寅":"태","丑":"양"},
        "壬":{"申":"장생","酉":"목욕","戌":"관대","亥":"건록","子":"제왕","丑":"쇠","寅":"병","卯":"사","辰":"묘","巳":"절","午":"태","未":"양"},
        "癸":{"卯":"장생","寅":"목욕","丑":"관대","子":"건록","亥":"제왕","戌":"쇠","酉":"병","申":"사","未":"묘","午":"절","巳":"태","辰":"양"},
    }

    # 년지 기준 12신살
    SHINSAL_MAP = {
        "子":{"申":"지살","酉":"도화","戌":"월살","亥":"망신","子":"장성","丑":"반안","寅":"역마","卯":"육해","辰":"화개","巳":"겁살","午":"재살","未":"천살"},
        "丑":{"巳":"지살","午":"도화","未":"월살","申":"망신","酉":"장성","戌":"반안","亥":"역마","子":"육해","丑":"화개","寅":"겁살","卯":"재살","辰":"천살"},
        "寅":{"寅":"지살","卯":"도화","辰":"월살","巳":"망신","午":"장성","未":"반안","申":"역마","酉":"육해","戌":"화개","亥":"겁살","子":"재살","丑":"천살"},
        "卯":{"亥":"지살","子":"도화","丑":"월살","寅":"망신","卯":"장성","辰":"반안","巳":"역마","午":"육해","未":"화개","申":"겁살","酉":"재살","戌":"천살"},
        "辰":{"申":"지살","酉":"도화","戌":"월살","亥":"망신","子":"장성","丑":"반안","寅":"역마","卯":"육해","辰":"화개","巳":"겁살","午":"재살","未":"천살"},
        "巳":{"巳":"지살","午":"도화","未":"월살","申":"망신","酉":"장성","戌":"반안","亥":"역마","子":"육해","丑":"화개","寅":"겁살","卯":"재살","辰":"천살"},
        "午":{"寅":"지살","卯":"도화","辰":"월살","巳":"망신","午":"장성","未":"반안","申":"역마","酉":"육해","戌":"화개","亥":"겁살","子":"재살","丑":"천살"},
        "未":{"亥":"지살","子":"도화","丑":"월살","寅":"망신","卯":"장성","辰":"반안","巳":"역마","午":"육해","未":"화개","申":"겁살","酉":"재살","戌":"천살"},
        "申":{"申":"지살","酉":"도화","戌":"월살","亥":"망신","子":"장성","丑":"반안","寅":"역마","卯":"육해","辰":"화개","巳":"겁살","午":"재살","未":"천살"},
        "酉":{"巳":"지살","午":"도화","未":"월살","申":"망신","酉":"장성","戌":"반안","亥":"역마","子":"육해","丑":"화개","寅":"겁살","卯":"재살","辰":"천살"},
        "戌":{"寅":"지살","卯":"도화","辰":"월살","巳":"망신","午":"장성","未":"반안","申":"역마","酉":"육해","戌":"화개","亥":"겁살","子":"재살","丑":"천살"},
        "亥":{"亥":"지살","子":"도화","丑":"월살","寅":"망신","卯":"장성","辰":"반안","巳":"역마","午":"육해","未":"화개","申":"겁살","酉":"재살","戌":"천살"},
    }

    cur_age = current_year - birth_year

    # ── 셀 헬퍼 ──────────────────────────────────
    def _hdr(text, bg="#3e2723", fg="#fff", sz=12, extra=""):
        return (f'<td style="background:{bg};color:{fg};font-size:{sz}px;'
                f'font-weight:700;text-align:center;padding:7px 3px;'
                f'border:1px solid #bbb;{extra}">{text}</td>')

    def _cg_td(cg, highlight=False):
        c = CG_COLOR.get(cg, "#666")
        brd = "border:3px solid #c62828;" if highlight else "border:1px solid #bbb;"
        kr = CG_KR.get(cg, "")
        return (f'<td style="background:{c};color:#fff;font-size:clamp(14px, 4vw, 22px);font-weight:900;'
                f'text-align:center;padding:clamp(6px, 2vw, 12px) clamp(2px, 1vw, 4px);{brd}">'
                f'{cg}<br><span style="font-size:10px;font-weight:500;">{kr}</span></td>')

    def _jj_td(jj, highlight=False):
        c = JJ_COLOR.get(jj, "#666")
        brd = "border:3px solid #c62828;" if highlight else "border:1px solid #bbb;"
        kr = JJ_KR.get(jj, "")
        return (f'<td style="background:{c};color:#fff;font-size:clamp(14px, 4vw, 22px);font-weight:900;'
                f'text-align:center;padding:clamp(6px, 2vw, 12px) clamp(2px, 1vw, 4px);{brd}">'
                f'{jj}<br><span style="font-size:10px;font-weight:500;">{kr}</span></td>')

    def _info(text, bg="#faf5ee", fg="#3e2723", sz=11, highlight=False):
        brd = "border:3px solid #c62828;" if highlight else "border:1px solid #bbb;"
        return (f'<td style="background:{bg};color:{fg};font-size:{sz}px;'
                f'text-align:center;padding:6px 3px;{brd}">{text}</td>')

    # ── 1단: 사주 명식 표 ─────────────────────────
    col_labels = ["시주(時)", "일주(日) ★", "월주(月)", "년주(年)"]
    ss_row = [_ss(ilgan, cg) for cg in cg_list]
    ss_row[1] = "일간(나)"  # 일간 자리는 고정
    us_row = [UNSEONG.get(ilgan, {}).get(jj, "—") for jj in jj_list]
    sh_row = [SHINSAL_MAP.get(nyeon_jj, {}).get(jj, "—") for jj in jj_list]

    r_hdr = "".join(_hdr(col_labels[i], "#3e2723" if i != 1 else "#c62828") for i in range(4))
    r_ss  = "".join(_info(ss_row[i]) for i in range(4))
    r_cg  = "".join(_cg_td(cg_list[i], i == 1) for i in range(4))
    r_jj  = "".join(_jj_td(jj_list[i]) for i in range(4))
    r_jg  = "".join(_info(JJ_JG.get(jj_list[i], "—"), "#fff3e0", "#bf360c", 10) for i in range(4))
    r_us  = "".join(_info(us_row[i], "#e3f2fd", "#0d47a1", 10) for i in range(4))
    r_sh  = "".join(_info(sh_row[i], "#e8f5e9", "#1b5e20", 10) for i in range(4))

    saju_table = f"""
<div style="margin:16px 0 8px;">
  <div style="font-size:13px;color:#6b4423;font-weight:700;text-align:center;margin-bottom:8px;letter-spacing:2px;">
    📋 사주 명식(四柱命式)
  </div>
  <div style="overflow-x:auto;">
  <table style="width:100%;border-collapse:collapse;table-layout:fixed;min-width:320px;">
    <tr>{r_hdr}</tr>
    <tr>{r_ss}</tr>
    <tr>{r_cg}</tr>
    <tr>{r_jj}</tr>
    <tr><td colspan="4" style="background:#f5f5f5;color:#888;font-size:10px;padding:3px 6px;border:1px solid #bbb;">지장간(支藏干)</td></tr>
    <tr>{r_jg}</tr>
    <tr><td colspan="4" style="background:#f5f5f5;color:#888;font-size:10px;padding:3px 6px;border:1px solid #bbb;">12운성(運星)</td></tr>
    <tr>{r_us}</tr>
    <tr><td colspan="4" style="background:#f5f5f5;color:#888;font-size:10px;padding:3px 6px;border:1px solid #bbb;">12신살(神殺) — 년지 기준</td></tr>
    <tr>{r_sh}</tr>
  </table>
  </div>
</div>"""

    # ── 2단: 대운 표 ────────────────────────────
    daewoon_table = ""
    if daewoon_list and isinstance(daewoon_list, list):
        dw_items = [d for d in daewoon_list if isinstance(d, dict)][:10]
        if dw_items:
            r_age = r_dss = r_dcg = r_djj = r_dus = ""
            for dw in dw_items:
                age  = dw.get("시작나이", "?")
                dcg  = dw.get("cg", "")
                djj  = dw.get("jj", "")
                hl   = bool(dw.get("is_current", False))
                dss  = _ss(ilgan, dcg)
                dus  = UNSEONG.get(ilgan, {}).get(djj, "—")
                brd  = "border:3px solid #c62828;" if hl else "border:1px solid #bbb;"
                r_age += (f'<td style="background:#3e2723;color:#fff;font-size:13px;'
                          f'font-weight:700;text-align:center;padding:7px 3px;{brd}">{age}</td>')
                r_dss += _info(dss, highlight=hl)
                r_dcg += _cg_td(dcg, hl)
                r_djj += _jj_td(djj, hl)
                r_dus += _info(dus, "#e3f2fd", "#0d47a1", 10, hl)

            daewoon_table = f"""
<div style="margin:16px 0 8px;">
  <div style="font-size:13px;color:#6b4423;font-weight:700;text-align:center;margin-bottom:8px;letter-spacing:2px;">
    🌊 대운(大運) — 10년 단위
  </div>
  <div style="overflow-x:auto;">
  <table style="width:100%;border-collapse:collapse;table-layout:fixed;min-width:560px;">
    <tr>{r_age}</tr>
    <tr>{r_dss}</tr>
    <tr>{r_dcg}</tr>
    <tr>{r_djj}</tr>
    <tr>{r_dus}</tr>
  </table>
  </div>
  <div style="font-size:10px;color:#c62828;margin-top:6px;text-align:center;font-weight:700;">
    빨간 박스 = 현재 진행 중 대운
  </div>
</div>"""

    # ── 3단: 세운 표 ────────────────────────────
    GAPJA60 = ['甲子','乙丑','丙寅','丁卯','戊辰','己巳','庚午','辛未','壬申','癸酉',
               '甲戌','乙亥','丙子','丁丑','戊寅','己卯','庚辰','辛巳','壬午','癸未',
               '甲申','乙酉','丙戌','丁亥','戊子','己丑','庚寅','辛卯','壬辰','癸巳',
               '甲午','乙未','丙申','丁酉','戊戌','己亥','庚子','辛丑','壬寅','癸卯',
               '甲辰','乙巳','丙午','丁未','戊申','己酉','庚戌','辛亥','壬子','癸丑',
               '甲寅','乙卯','丙辰','丁巳','戊午','己未','庚申','辛酉','壬戌','癸亥']

    def _yr_ganji(yr):
        return GAPJA60[(yr - 1984) % 60]

    r_yr = r_yss = r_ycg = r_yjj = ""
    for offset in range(-3, 7):
        yr = current_year + offset
        gj = _yr_ganji(yr)
        ycg, yjj = gj[0], gj[1]
        hl = (yr == current_year)
        yss = _ss(ilgan, ycg)
        brd = "border:3px solid #c62828;" if hl else "border:1px solid #bbb;"
        yr_bg = "#c62828" if hl else "#3e2723"
        r_yr  += (f'<td style="background:{yr_bg};color:#fff;font-size:12px;'
                  f'font-weight:700;text-align:center;padding:7px 2px;{brd}">{yr}</td>')
        r_yss += _info(yss, highlight=hl)
        r_ycg += _cg_td(ycg, hl)
        r_yjj += _jj_td(yjj, hl)

    sewoon_table = f"""
<div style="margin:16px 0 8px;">
  <div style="font-size:13px;color:#6b4423;font-weight:700;text-align:center;margin-bottom:8px;letter-spacing:2px;">
    📅 세운(歲運) — 매년 운세
  </div>
  <div style="overflow-x:auto;">
  <table style="width:100%;border-collapse:collapse;table-layout:fixed;min-width:560px;">
    <tr>{r_yr}</tr>
    <tr>{r_yss}</tr>
    <tr>{r_ycg}</tr>
    <tr>{r_yjj}</tr>
  </table>
  </div>
  <div style="font-size:10px;color:#c62828;margin-top:6px;text-align:center;font-weight:700;">
    빨간 박스 = {current_year}년 (현재)
  </div>
</div>"""

    # ── 전체 조합 ─────────────────────────────
    html = f"""
<div style="background:#fff;border:3px solid #3e2723;border-radius:16px;
            padding:22px 18px;margin:18px 0;
            box-shadow:0 8px 24px rgba(62,39,35,0.15);
            font-family:'Noto Sans KR',sans-serif;">

  <div style="text-align:center;margin-bottom:16px;border-bottom:2px solid #6b4423;padding-bottom:12px;">
    <div style="font-size:12px;color:#8b6914;letter-spacing:4px;font-weight:700;">⚱️ 정통 명리학 만세력 ⚱️</div>
    <div style="font-size:clamp(14px, 3.5vw, 20px);font-weight:900;color:#3e2723;margin-top:6px;">{name}님 만세력 보드</div>
    <div style="font-size:11px;color:#6b4423;margin-top:4px;">{birth_year}년생 {gender} — {current_year}년 기준</div>
  </div>

  {saju_table}
  <hr style="border:none;border-top:1px dashed #6b4423;margin:18px 0;">
  {daewoon_table}
  <hr style="border:none;border-top:1px dashed #6b4423;margin:18px 0;">
  {sewoon_table}

  <div style="text-align:center;font-size:10px;color:#8b6914;margin-top:14px;padding-top:10px;border-top:1px dashed #6b4423;">
    색상 — 木(녹) · 火(빨) · 土(주황) · 金(회) · 水(파)&nbsp;&nbsp;|&nbsp;&nbsp;★ 일주(日柱) = 본인
  </div>
</div>
"""
    return html


# ═══════════════════════════════════════════════════════════════════
# Y-28: 신살 풀세트 계산 — 정통 명리학 기준 12종
# ═══════════════════════════════════════════════════════════════════
def calc_all_sinsal_extended(pils):
    """정통 명리학 기준 신살 전체 계산 (12종). 기존 saju_sinsal과 중복 없이 보완."""
    if not pils or len(pils) < 4:
        return []

    ilgan = pils[1].get("cg", "")
    iljj  = pils[1].get("jj", "")
    cgs   = [p.get("cg", "") for p in pils]
    jjs   = [p.get("jj", "") for p in pils]
    iz_key = ilgan + iljj
    wj_jj  = jjs[2] if len(jjs) > 2 else ""

    results = []

    # 1. 홍염살(紅艶煞) — 매력·이성 인연
    HONGYEOM = {
        "甲":"午","乙":"午","丙":"寅","丁":"未",
        "戊":"辰","己":"辰","庚":"戌","辛":"酉","壬":"子","癸":"申",
    }
    _hy = HONGYEOM.get(ilgan)
    if _hy and _hy in jjs:
        _pos = ["시","일","월","년"][jjs.index(_hy)]
        results.append({"이름":"홍염살(紅艶煞)","위치":f"{_pos}지({_hy})",
            "의미":"타고난 매력과 이성 인연이 강한 신살",
            "발동":f"{ilgan} 일간 + {_hy}지 — 매력 발동",
            "결과":"이성에게 강하게 끌리고/끌림. 연예·서비스 분야 빛남.",
            "주의":"기혼자 외도 위험. 합·도화 운에 인연 폭발.",
            "활용":"서비스·연예·상담·예술 직업 최적.",
            "아이콘":"🌹","등급":"발동"})

    # 2. 백호대살(白虎大煞) — 일주 기준
    BAEKHO = ["甲辰","乙未","丙戌","丁丑","戊辰","壬戌","癸丑"]
    if iz_key in BAEKHO:
        results.append({"이름":"백호대살(白虎大煞)","위치":f"일주({iz_key})",
            "의미":"강한 살기 — 혈광지재 가능",
            "발동":f"일주 {iz_key} — 백호 7대 일주 중 하나",
            "결과":"사고·수술·혈광지재 위험. 일가족 풍파 가능.",
            "주의":"운전·수술·격투기 평생 신중. 충 운에 절정.",
            "활용":"군경·외과·검사·소방 — 살을 권으로.",
            "아이콘":"🐅","등급":"강력발동"})

    # 3. 괴강살(魁罡煞) — 일주 기준
    GOEGANG = ["庚辰","庚戌","壬辰","壬戌","戊戌","戊辰"]
    if iz_key in GOEGANG:
        results.append({"이름":"괴강살(魁罡煞)","위치":f"일주({iz_key})",
            "의미":"극강한 권력·총명·고집의 신살",
            "발동":f"일주 {iz_key} — 괴강 6대 일주 중 하나",
            "결과":"극강한 권력욕과 카리스마. 부귀 양극단.",
            "주의":"인간관계 충돌 잦음. 부부 인연 험난.",
            "활용":"리더·법조·군경·정치 — 정상권 가능.",
            "아이콘":"👑","등급":"강력발동"})

    # 4. 곡각살(曲脚煞) — 천간+지지 결합
    if any(c in ["乙","己"] for c in cgs) and any(j in ["巳","丑"] for j in jjs):
        results.append({"이름":"곡각살(曲脚煞)","위치":"원국",
            "의미":"뼈·관절·다리 약함 신살",
            "발동":"천간 乙·己 + 지지 巳·丑 결합",
            "결과":"골절·관절·다리 부상 잦음.",
            "주의":"운동·계단·등산 주의. 골다공증 검진.",
            "활용":"스트레칭·근력 운동 꾸준히.",
            "아이콘":"🦵","등급":"발동"})

    # 5. 음양차착살(陰陽差錯) — 일주 기준
    CHACHAK = ["丙子","丁丑","戊寅","辛卯","壬辰","癸巳",
               "丙午","丁未","戊申","辛酉","壬戌","癸亥"]
    if iz_key in CHACHAK:
        results.append({"이름":"음양차착살(陰陽差錯)","위치":f"일주({iz_key})",
            "의미":"결혼·인연 어긋남 신살",
            "발동":f"일주 {iz_key} — 차착 12대 일주",
            "결과":"결혼 늦거나 배우자 인연 어긋남.",
            "주의":"결혼 결정 신중. 배우자 가문 갈등 주의.",
            "활용":"늦은 결혼이 오히려 안정. 만혼 권장.",
            "아이콘":"💔","등급":"발동"})

    # 6. 효신살(梟神煞) — 일주 기준 (편인 일지)
    HYOSHIN = ["甲子","乙亥","丙寅","丁卯","戊午",
               "己巳","庚辰","庚戌","辛丑","辛未","壬申","癸酉"]
    if iz_key in HYOSHIN:
        results.append({"이름":"효신살(梟神煞)","위치":f"일주({iz_key})",
            "의미":"편인이 일지에 — 어머니·인성 갈등",
            "발동":f"일주 {iz_key} — 일지에 편인",
            "결과":"어머니와 갈등. 의존성·고독감.",
            "주의":"결혼 후 시댁/처가 인성 충돌. 우울 주의.",
            "활용":"독립·자립 능력 키우면 강점.",
            "아이콘":"🦉","등급":"발동"})

    # 7. 복성귀인(福星貴人) — 일간+지지
    BOKSEONG = {"甲":"寅","乙":"丑","丙":"子","丁":"酉",
                "戊":"申","己":"未","庚":"午","辛":"巳","壬":"辰","癸":"卯"}
    _bk = BOKSEONG.get(ilgan)
    if _bk and _bk in jjs:
        _pos = ["시","일","월","년"][jjs.index(_bk)]
        results.append({"이름":"복성귀인(福星貴人)","위치":f"{_pos}지({_bk})",
            "의미":"평생 복덕·재물 유지 신살",
            "발동":f"{ilgan} 일간 + {_bk}지",
            "결과":"평생 복록·재물·인덕이 따라옴.",
            "주의":"복은 나누어야 늘어남. 인색 X.",
            "활용":"베풂이 곧 자기 복.",
            "아이콘":"🍀","등급":"발동"})

    # 8. 천덕귀인(天德貴人) — 월지 기준
    CHEONDEOK = {"寅":"丁","卯":"申","辰":"壬","巳":"辛","午":"亥","未":"甲",
                 "申":"癸","酉":"寅","戌":"丙","亥":"乙","子":"巳","丑":"庚"}
    _cd = CHEONDEOK.get(wj_jj)
    if _cd and (_cd in cgs or _cd in jjs):
        results.append({"이름":"천덕귀인(天德貴人)","위치":"원국",
            "의미":"하늘의 덕 — 위기 시 자연스러운 도움",
            "발동":f"월지 {wj_jj} → 천덕 {_cd} 발현",
            "결과":"위기에 자연스럽게 도움. 인복 평생.",
            "주의":"복을 당연시 X. 베풂이 핵심.",
            "활용":"봉사·기부 — 복이 배가.",
            "아이콘":"🌟","등급":"발동"})

    # 9. 월덕귀인(月德貴人) — 월지 기준
    WOLDEOK = {"寅":"丙","午":"丙","戌":"丙","申":"壬","子":"壬","辰":"壬",
               "巳":"庚","酉":"庚","丑":"庚","亥":"甲","卯":"甲","未":"甲"}
    _wd = WOLDEOK.get(wj_jj)
    if _wd and _wd in cgs:
        results.append({"이름":"월덕귀인(月德貴人)","위치":"원국",
            "의미":"월의 덕 — 평생 안정·평온",
            "발동":f"월지 {wj_jj} → 월덕 {_wd} 발현",
            "결과":"평생 안정·평온·인복.",
            "주의":"안주 X — 노력 필수.",
            "활용":"꾸준한 노력 = 평생 결실.",
            "아이콘":"🌙","등급":"발동"})

    # 10. 금여성(金輿星) — 일간+지지
    GEUMYEO = {"甲":"辰","乙":"巳","丙":"未","丁":"申","戊":"未",
               "己":"申","庚":"戌","辛":"亥","壬":"丑","癸":"寅"}
    _gy = GEUMYEO.get(ilgan)
    if _gy and _gy in jjs:
        _pos = ["시","일","월","년"][jjs.index(_gy)]
        results.append({"이름":"금여성(金輿星)","위치":f"{_pos}지({_gy})",
            "의미":"귀한 인연·배우자 만남 신살",
            "발동":f"{ilgan} 일간 + {_gy}지",
            "결과":"귀한 배우자·재물 인연. 평온한 결혼.",
            "주의":"교만 X. 인연 소중히.",
            "활용":"결혼·인연 적극.",
            "아이콘":"💍","등급":"발동"})

    # 11. 암록(暗祿) — 일간+지지
    AMROK = {"甲":"亥","乙":"戌","丙":"申","丁":"未","戊":"申","己":"未",
             "庚":"巳","辛":"辰","壬":"寅","癸":"丑"}
    _ar = AMROK.get(ilgan)
    if _ar and _ar in jjs:
        _pos = ["시","일","월","년"][jjs.index(_ar)]
        results.append({"이름":"암록(暗祿)","위치":f"{_pos}지({_ar})",
            "의미":"숨은 도움 — 보이지 않는 복록",
            "발동":f"{ilgan} 일간 + {_ar}지",
            "결과":"위기에 숨은 도움 등장. 평생 인복.",
            "주의":"드러내지 않는 복.",
            "활용":"내실·신뢰 — 복이 늘어남.",
            "아이콘":"🔮","등급":"발동"})

    # 13. 천을귀인(天乙貴人) — 일간 기준, 정통 명리학 최강 길성
    CHEONUL = {
        "甲": ["丑","未"], "戊": ["丑","未"], "庚": ["丑","未"],
        "乙": ["子","申"], "己": ["子","申"],
        "丙": ["酉","亥"], "丁": ["酉","亥"],
        "辛": ["寅","午"],
        "壬": ["巳","卯"], "癸": ["巳","卯"],
    }
    _cu_list = CHEONUL.get(ilgan, [])
    _cu_found = []
    for _cu in _cu_list:
        if _cu in jjs:
            _cu_pos = ["시","일","월","년"][jjs.index(_cu)]
            _cu_found.append(f"{_cu_pos}지({_cu})")
    if _cu_found:
        results.append({
            "이름": "천을귀인(天乙貴人)",
            "위치": ", ".join(_cu_found),
            "의미": "위기 시 도움 주는 최강 길성 — 평생 귀인복",
            "발동": f"{ilgan} 일간 + {'·'.join(_cu_list)}지",
            "결과": "막다른 순간 반드시 누군가 손 내밀어 줍니다. 60갑자 중 상위 10%만 가진 보물.",
            "주의": "복을 당연시 X. 인간관계 절대 소홀히 X.",
            "활용": "활성월 6월·12월 — 사람·미팅·기회 절대 거절 X. 귀인은 이미 가까이.",
            "아이콘": "👼",
            "등급": "강력발동",
        })

    # 14. 문창귀인(文昌貴人) — 일간 기준
    MUNCHANG = {
        "甲": "巳", "乙": "午",
        "丙": "申", "丁": "酉",
        "戊": "申", "己": "酉",
        "庚": "亥", "辛": "子",
        "壬": "寅", "癸": "卯",
    }
    _mc = MUNCHANG.get(ilgan)
    if _mc and _mc in jjs:
        _mc_pos = ["시","일","월","년"][jjs.index(_mc)]
        results.append({
            "이름": "문창귀인(文昌貴人)",
            "위치": f"{_mc_pos}지({_mc})",
            "의미": "학문·글·말 능력의 최강 길성",
            "발동": f"{ilgan} 일간 + {_mc}지",
            "결과": "글·말·학문 능력 60갑자 중 상위. 강의·작가·교육·법조·역술 분야 강점.",
            "주의": "재능을 묻지 마세요. 표현하는 일 절대 피하지 X.",
            "활용": "콘텐츠·강의·책·SNS — 부수입 가능. 표현하는 일이 곧 운명.",
            "아이콘": "📚",
            "등급": "강력발동",
        })

    # 15. 학당귀인(學堂貴人) — 일간 기준
    HAKDANG = {
        "甲": "亥", "乙": "午",
        "丙": "寅", "丁": "酉",
        "戊": "寅", "己": "酉",
        "庚": "巳", "辛": "子",
        "壬": "申", "癸": "卯",
    }
    _hd = HAKDANG.get(ilgan)
    if _hd and _hd in jjs:
        _hd_pos = ["시","일","월","년"][jjs.index(_hd)]
        _is_dup = (_hd == _mc) and any("문창" in r.get("이름","") for r in results)
        if not _is_dup:
            results.append({
                "이름": "학당귀인(學堂貴人)",
                "위치": f"{_hd_pos}지({_hd})",
                "의미": "공부·연구·학문 분야 길성",
                "발동": f"{ilgan} 일간 + {_hd}지",
                "결과": "두뇌 회전 빠르고 자기 계발 의지 강합니다. 학업·자격증 운 최강.",
                "주의": "재능을 묻지 마세요. 꾸준한 학습 필수.",
                "활용": "전문 자격증·박사학위·교육 분야 도전.",
                "아이콘": "🎓",
                "등급": "발동",
            })

    # 12. 십악대패일(十惡大敗日) — 일주 기준
    SIBAK = ["甲辰","乙巳","壬申","丙申","丁亥",
             "庚辰","戊戌","癸亥","辛巳","己丑"]
    if iz_key in SIBAK:
        results.append({"이름":"십악대패일(十惡大敗日)","위치":f"일주({iz_key})",
            "의미":"재물·노력 헛수고 일주",
            "발동":f"일주 {iz_key} — 십악 10대 일주",
            "결과":"노력 대비 결과 약함. 한 번에 무너짐.",
            "주의":"큰 결정 신중. 동업·투자 X.",
            "활용":"꾸준한 노력·축적 전략.",
            "아이콘":"⚠️","등급":"발동"})

    return results
